from itertools import product, permutations, combinations
cols='rgb'; objs='kcm'; init={'k':'r','c':'g','m':'b'}
# actions as assumed; track phys positions and labels mapping label->phys.
outs={}; sols=[]
for O1,O2,O3,O4,O5 in product(objs, repeat=5):
    oc={o:[O1,O2,O3,O4,O5].count(o) for o in objs}
    if any(v>2 for v in oc.values()): continue
    # require deficits sum1 mention, so counts [2,2,1]
    if sorted(oc.values()) "'!= [1,2,2]: continue
    for C1,C2 in permutations(cols,2):
      if init[O1]!=C1: continue
      for C3,C4 in combinations(cols,2):
       # action2 label names, order irrelevant
       for C5,C6 in permutations(cols,2):
        for C7,C8 in combinations(cols,2):
         for C9,C10 in product(cols,repeat=2):
          cc={x:[C1,C2,C3,C4,C5,C6,C7,C8,C9,C10].count(x) for x in cols}
          if sorted(cc.values()) != [3,3,4]: continue
          if cc!={'"'r':4,'g':3,'b':3}: continue
          pos=init.copy(); l2p={x:x for x in cols}
          pos[O1]=l2p[C2]
          l2p[C3],l2p[C4]=l2p[C4],l2p[C3]
          if pos[O2]"'!=l2p[C5]: continue
          pos[O2]=l2p[C6]
          p7,p8=l2p[C7],l2p[C8]
          for o in objs:
            if pos[o]==p7:pos[o]=p8
            elif pos[o]==p8:pos[o]=p7
          empt=[p for p in cols if p not in pos.values()]
          if len(empt)!=1: continue
          if pos[O3]!=l2p[C9]:continue
          pos[O3]=empt[0]
          if pos[O4]!=l2p[C10]:continue
          dest=pos[O5]
          if pos[O4]==dest: continue
          pos[O4]=dest
          p2l={p:l for l,p in l2p.items()}
          out=tuple(p2l[pos[o]] for o in objs)
          outs[out]=outs.get(out,0)+1
          if len(sols)<20:sols.append(((O1,C1,C2),(C3,C4),(O2,C5,C6),(C7,C8),(O3,C9),(O4,C10,O5),out,oc))
print('"'n',sum(outs.values()),'outputs',len(outs),sorted(outs.items(),key=lambda x:-x[1])[:20])
for s in sols:print(s)
PY"

