from itertools import permutations,combinations,product
cols='rgb'; init={'k':'r','c':'g','m':'b'}
sol=[]
# fixed targets. final direction source color C10 -> box containing m
for X in 'gb':
 for sp1 in combinations(cols,2):
  for c5,c6 in permutations(cols,2):
   for sp2 in combinations(cols,2):
    for c9,c10 in product(cols,repeat=2):
     args=['r',X,*sp1,c5,c6,*sp2,c9,c10]
     if {c:args.count(c) for c in cols}"'!={'"'r':4,'g':3,'b':3}:continue
     pos=init.copy(); l2p={c:c for c in cols}
     pos['k']=l2p[X]
     l2p[sp1[0]],l2p[sp1[1]]=l2p[sp1[1]],l2p[sp1[0]]
     if pos['m']"'!=l2p[c5]:continue
     pos['"'m']=l2p[c6]
     p,q=l2p[sp2[0]],l2p[sp2[1]]
     for o in pos:
      if pos[o]==p:pos[o]=q
      elif pos[o]==q:pos[o]=p
     empt=[p for p in cols if p not in pos.values()]
     if len(empt)"'!=1 or pos['"'c']"'!=l2p[c9]:continue
     pos['"'c']=empt[0]
     if pos['k']"'!=l2p[c10] or pos['"'k']==pos['m']:continue
     pos['k']=pos['m']
     p2l={p:l for l,p in l2p.items()}
     out=tuple(p2l[pos[o]] for o in 'kcm')
     sol.append((X,sp1,(c5,c6),sp2,c9,c10,out))
print(len(sol))
for x in sol:print(x)
